@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ink:#eff4e9;--muted:#a9b5a9;--mint:#a9efb2;--red:#ed8275;--glass:rgba(17,27,24,.82);--line:rgba(224,241,221,.13)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#18251d;color:var(--ink);font-family:Manrope,system-ui,sans-serif;user-select:none;-webkit-user-select:none}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:420px;overflow:hidden;background:#344532}canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(10,18,16,.91),rgba(10,18,16,.48));border-bottom:1px solid rgba(255,255,255,.09)}.brand{display:flex;align-items:center;gap:12px;min-width:220px}.brand-mark{width:37px;height:37px;border:1px solid rgba(177,239,180,.5);border-radius:11px;display:grid;place-items:center;color:#b8f5b5;font-size:21px;background:rgba(137,208,139,.12);box-shadow:0 0 24px rgba(118,202,122,.13)}.brand strong{display:block;font-size:14px;letter-spacing:.18em;font-weight:800}.brand span{display:block;margin-top:3px;font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#9da99c}.brand span i{color:#8fdb98;font-style:normal}.match-info{font:10px 'DM Mono',monospace;letter-spacing:.14em;color:#c1cbbf;display:flex;align-items:center;gap:10px}.match-info b{color:#657467;font-weight:400}.live-dot{height:7px;width:7px;border-radius:50%;background:#a4ec9f;box-shadow:0 0 10px #a4ec9f}.icon-button{width:37px;height:37px;border:1px solid var(--line);border-radius:10px;background:rgba(255,255,255,.045);font-size:17px;color:#cbd6c8;cursor:pointer;transition:.2s}.icon-button:hover,.icon-button.muted{background:rgba(255,255,255,.12);color:white}
.glass{background:var(--glass);border:1px solid var(--line);box-shadow:0 14px 40px rgba(3,10,7,.2);backdrop-filter:blur(12px)}.mission-card{position:absolute;z-index:2;left:34px;top:105px;width:286px;padding:19px 20px 15px;border-radius:13px}.eyebrow{display:flex;gap:9px;align-items:center;color:#a8e7a9;font:9px 'DM Mono',monospace;letter-spacing:.17em}.eyebrow-line{width:17px;height:1px;background:#a8e7a9}.mission-card h1{font-size:25px;letter-spacing:-.04em;margin:11px 0 5px;font-weight:700}.mission-card p{font-size:11px;color:#b8c2b5;margin:0 0 16px}.red-text{color:#f09485}.objective-row{border-top:1px solid var(--line);padding-top:12px;display:flex;align-items:center;gap:10px}.objective-icon{height:31px;width:31px;border-radius:9px;background:rgba(222,107,91,.15);display:grid;place-items:center;color:#f28d7e;font-size:18px}.objective-row strong{display:block;font-size:11px;font-weight:700}.objective-row small{display:block;margin-top:3px;color:#a3afa1;font:9px 'DM Mono',monospace}.objective-arrow{margin-left:auto;color:#bdc8b9;font-size:17px}
.minimap{position:absolute;z-index:2;top:105px;right:34px;width:194px;border-radius:12px;padding:12px 13px 10px}.mini-head{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#c7d0c4}.mini-live{color:#a7eaa3;font-size:7px}.mini-map{height:84px;position:relative;margin:10px 0 5px;border-radius:8px;overflow:hidden;background:radial-gradient(ellipse at 50% 50%,rgba(136,169,112,.18),rgba(34,54,39,.32)),#28392d;border:1px solid rgba(255,255,255,.06)}.mini-lane{height:12px;width:132%;position:absolute;left:-16%;top:38px;transform:rotate(-28deg);background:rgba(190,187,145,.24);border-top:1px solid rgba(238,226,180,.25);border-bottom:1px solid rgba(238,226,180,.2)}.mini-base{position:absolute;width:12px;height:12px;border-radius:3px;transform:rotate(45deg);top:61px}.mini-base.blue{left:16px;background:#75b9ff;box-shadow:0 0 10px #75b9ff}.mini-base.red{right:16px;top:10px;background:#ee8078;box-shadow:0 0 10px #ee8078}.mini-hero,.mini-tower{position:absolute;width:7px;height:7px;border-radius:50%;top:59px;left:28px;background:#e6f4cf;border:1px solid #fff;box-shadow:0 0 7px #dafaaf;transition:left .2s,top .2s}.mini-tower{top:34px;left:96px;background:#f38c7c;box-shadow:0 0 8px #f38c7c}.mini-labels{display:flex;justify-content:space-between;color:#869488;font:7px 'DM Mono',monospace;letter-spacing:.12em}
.side-note{position:absolute;right:34px;bottom:115px;border-radius:9px;padding:10px 13px;display:flex;align-items:center;gap:10px;color:#c2cdc0;font-size:9px;line-height:1.55}.side-note b{font-weight:600;color:#e3e9dd}.note-icon{font-size:17px;color:#a7e5a8}.bottom-hud{position:absolute;z-index:3;left:34px;right:34px;bottom:24px;display:flex;align-items:center;gap:18px}.hero-card{height:76px;width:286px;display:flex;align-items:center;gap:12px;padding:10px 13px;border-radius:12px}.portrait{width:46px;height:46px;position:relative;display:grid;place-items:center;border-radius:10px;background:linear-gradient(145deg,#566c4c,#1f3029);border:1px solid rgba(186,221,157,.35);box-shadow:inset 0 0 20px rgba(174,227,155,.12)}.portrait-glyph{font-size:30px;color:#d4dfc6;line-height:1}.level-badge{position:absolute;left:-5px;top:-5px;width:15px;height:15px;border-radius:50%;background:#d6bd73;color:#1c2118;display:grid;place-items:center;font:8px 'DM Mono',monospace;font-style:normal;font-weight:700;border:1px solid #f3d996}.online-dot{position:absolute;width:8px;height:8px;border-radius:50%;right:3px;bottom:3px;background:#9be89a;border:1px solid #1b2b21;box-shadow:0 0 7px #9be89a}.hero-meta{flex:1;min-width:0}.hero-name{font-size:10px;letter-spacing:.1em;font-weight:800}.hero-name span{margin-left:4px;color:#adc4a5;font:8px 'DM Mono',monospace}.hero-role{margin-top:4px;color:#a4b09f;font:8px 'DM Mono',monospace;letter-spacing:.06em}.hero-role i{color:#8fda96;font-style:normal}.hero-health{display:flex;align-items:center;gap:8px;margin-top:8px}.health-track{height:4px;background:rgba(0,0,0,.4);border-radius:5px;flex:1;overflow:hidden}.health-track i{display:block;height:100%;width:100%;background:#98d993;border-radius:5px}.hero-health b{font:8px 'DM Mono',monospace;color:#dce7d7}.controls-hint{margin:auto;display:flex;align-items:center;gap:8px;color:#d0d9cb;font:8px 'DM Mono',monospace;letter-spacing:.1em;text-shadow:0 1px 5px #111}.mouse-icon{width:20px;height:19px;display:grid;place-items:center;border:1px solid rgba(242,246,233,.55);border-radius:5px;color:#e2eadb;font:bold 9px 'DM Mono',monospace;background:rgba(17,25,19,.4)}.target-icon{font-size:14px}.hint-divider{color:#99a494}.attack-button{height:60px;width:194px;border:1px solid rgba(165,237,164,.42);border-radius:11px;background:linear-gradient(120deg,rgba(73,116,75,.94),rgba(38,70,50,.95));display:flex;align-items:center;gap:11px;padding:0 14px;text-align:left;cursor:pointer;box-shadow:0 8px 25px rgba(4,15,8,.27);transition:.18s}.attack-button:hover{filter:brightness(1.16);transform:translateY(-1px)}.attack-button:active{transform:translateY(1px)}.attack-symbol{font-size:23px;color:#d4f1c6}.attack-button b{display:block;font-size:10px;letter-spacing:.13em}.attack-button small{display:block;color:#b9cbb4;font:8px 'DM Mono',monospace;margin-top:4px}.attack-button kbd{margin-left:auto;border:1px solid rgba(255,255,255,.22);border-radius:4px;padding:3px 5px;color:#c4d2bf;font:8px 'DM Mono',monospace}.attack-button.engaged{background:linear-gradient(120deg,rgba(120,74,57,.95),rgba(79,45,38,.96));border-color:rgba(237,130,117,.5)}
.joystick-wrap{display:none;position:absolute;z-index:4;left:24px;bottom:116px;width:116px;height:116px;touch-action:none}.joy-ring{position:absolute;inset:0;border-radius:50%;background:rgba(19,31,25,.35);border:1px solid rgba(235,245,225,.2);box-shadow:inset 0 0 24px rgba(0,0,0,.22);backdrop-filter:blur(4px)}.joy-center{position:absolute;inset:24px;border:1px solid rgba(228,241,220,.12);border-radius:50%}.joy-knob{position:absolute;width:44px;height:44px;border-radius:50%;left:35px;top:35px;background:radial-gradient(circle at 35% 30%,rgba(212,242,198,.65),rgba(123,162,117,.48));border:1px solid rgba(240,249,230,.46);box-shadow:0 4px 12px rgba(0,0,0,.28)}.toast{position:absolute;z-index:8;top:91px;left:50%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:9px 14px;border:1px solid rgba(255,255,255,.15);border-radius:8px;background:rgba(15,24,20,.91);font:10px 'DM Mono',monospace;color:#e2e9dd;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.victory-overlay{position:absolute;z-index:7;inset:0;display:grid;place-items:center;background:rgba(8,14,12,.46);backdrop-filter:blur(3px);opacity:0;pointer-events:none;transition:opacity .45s}.victory-overlay.visible{opacity:1;pointer-events:auto}.victory-card{width:min(380px,calc(100vw - 32px));padding:32px;text-align:center;border-radius:18px}.victory-sigil{margin:0 auto 15px;width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:rgba(165,231,154,.12);border:1px solid rgba(165,231,154,.35);font-size:27px;color:#c8f1b3}.victory-card .eyebrow{justify-content:center}.victory-card h2{font-size:30px;margin:12px 0 8px}.victory-card p{font-size:12px;line-height:1.6;color:#b5c1b2}.victory-card button{margin-top:15px;width:100%;padding:12px;border:1px solid rgba(171,231,161,.38);border-radius:8px;background:#416347;color:#eaf3e3;font:10px 'DM Mono',monospace;letter-spacing:.12em;cursor:pointer}.victory-card button span{margin-left:8px}.sound-toast{position:absolute;z-index:8;right:34px;top:78px;font:9px 'DM Mono',monospace;color:#d3decf;background:rgba(15,24,20,.9);padding:7px 10px;border-radius:6px;opacity:0;transition:.2s}.sound-toast.show{opacity:1}
@media(max-width:760px){.topbar{height:60px;padding:0 16px}.brand{min-width:0;gap:9px}.brand-mark{width:32px;height:32px}.brand strong{font-size:11px}.brand span{font-size:7px}.match-info{font-size:8px;gap:5px}.mission-card{left:14px;top:74px;width:220px;padding:13px 14px}.mission-card h1{font-size:19px;margin-top:8px}.mission-card p{font-size:9px;margin-bottom:10px}.objective-row{padding-top:8px}.objective-icon{width:27px;height:27px}.objective-row strong{font-size:10px}.objective-row small{font-size:7px}.minimap{right:14px;top:74px;width:150px;padding:9px}.mini-map{height:65px;margin:7px 0 4px}.mini-lane{top:29px;height:9px}.mini-base.blue{top:47px}.mini-base.red{top:7px}.mini-hero{top:45px}.mini-tower{top:26px;left:74px}.side-note{display:none}.bottom-hud{left:12px;right:12px;bottom:12px;gap:8px}.hero-card{width:198px;height:62px;padding:7px;gap:8px}.portrait{height:42px;width:42px}.hero-name{font-size:8px}.hero-role{font-size:7px}.hero-health{margin-top:6px}.hero-health b{font-size:7px}.controls-hint{display:none}.attack-button{width:132px;height:54px;padding:0 9px;gap:7px}.attack-button kbd{display:none}.attack-symbol{font-size:19px}.attack-button b{font-size:8px}.attack-button small{font-size:7px}.joystick-wrap{display:block;left:16px;bottom:91px;width:102px;height:102px}.joy-knob{left:29px;top:29px;width:42px;height:42px}.joy-center{inset:20px}.sound-toast{top:63px;right:14px}.toast{top:67px}}
@media(max-width:390px){.match-info{display:none}.minimap{width:136px}.mission-card{width:198px}.hero-card{width:177px}.attack-button{width:119px}.hero-name span{margin-left:2px}.hero-role{letter-spacing:0}}

(() => {
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const towerState = { hp: 100, max: 100, dead: false };
  const hero = { t: .13, side: 0, destT: null, destSide: 0, moving: false, facing: 1 };
  let W = 0, H = 0, dpr = 1, last = performance.now(), elapsed = 0;
  let attackMode = false, attackTimer = 0, hitFlash = 0, projectile = null, soundOn = false;
  let joystick = { active: false, dx: 0, dy: 0 }, joyPointer = null, toastTimer = 0;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const mix = (a, b, t) => a + (b - a) * t;
  function lanePoint(t, side = 0) {
    const bx = W * .16, by = H * .75, rx = W * .84, ry = H * .24;
    const dx = rx - bx, dy = ry - by, len = Math.hypot(dx, dy), nx = -dy / len, ny = dx / len;
    return { x: bx + dx * t + nx * side, y: by + dy * t + ny * side, nx, ny, dx: dx / len, dy: dy / len };
  }
  function towerPoint() { return lanePoint(.54, 0); }
  function heroPoint() { return lanePoint(hero.t, hero.side); }
  function resize() {
    const r = canvas.getBoundingClientRect(); W = r.width; H = r.height; dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  addEventListener('resize', resize); resize();
  function path(points) { ctx.beginPath(); points.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)); ctx.closePath(); }
  function ellipse(x, y, rx, ry, fill, stroke, line = 1) { ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); if (fill) { ctx.fillStyle = fill; ctx.fill(); } if (stroke) { ctx.lineWidth = line; ctx.strokeStyle = stroke; ctx.stroke(); } }
  function line(x1, y1, x2, y2, color, width = 1) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke(); }
  function drawGround() {
    const grad = ctx.createLinearGradient(0, 0, W, H); grad.addColorStop(0, '#42543c'); grad.addColorStop(.52, '#354a35'); grad.addColorStop(1, '#283d32'); ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
    // Soft terrain patches and tiny vegetation flecks give the field depth without external assets.
    for (let i = 0; i < 38; i++) {
      const x = ((i * 193 + 31) % 997) / 997 * W, y = ((i * 317 + 73) % 991) / 991 * H;
      ellipse(x, y, 35 + (i % 5) * 9, 14 + (i % 4) * 5, i % 2 ? 'rgba(147,171,105,.045)' : 'rgba(10,26,19,.07)');
    }
    let seed = 49;
    for (let i = 0; i < Math.min(140, W * H / 6500); i++) {
      seed = (seed * 16807) % 2147483647; const x = seed / 2147483647 * W; seed = (seed * 16807) % 2147483647; const y = seed / 2147483647 * H;
      line(x, y, x + (seed % 5) - 2, y - 3 - seed % 4, 'rgba(200,218,156,.16)', 1);
    }
    // Distant pools and low-contrast lane-side stones
    for (let i = 0; i < 9; i++) { const p = lanePoint(i / 8, i % 2 ? 84 : -84); ellipse(p.x, p.y, 13, 7, 'rgba(184,183,137,.12)', 'rgba(220,213,167,.09)'); }
    const a = lanePoint(-.06), b = lanePoint(1.07);
    line(a.x, a.y, b.x, b.y, 'rgba(12,21,16,.22)', 112);
    line(a.x, a.y, b.x, b.y, 'rgba(204,195,150,.22)', 92);
    line(a.x, a.y, b.x, b.y, 'rgba(160,153,119,.53)', 82);
    line(a.x, a.y, b.x, b.y, 'rgba(202,194,158,.54)', 74);
    line(a.x, a.y, b.x, b.y, 'rgba(145,150,119,.48)', 67);
    // Worn path seams
    const laneA = lanePoint(.02, -28), laneB = lanePoint(.98, -28), laneC = lanePoint(.02, 28), laneD = lanePoint(.98, 28);
    line(laneA.x, laneA.y, laneB.x, laneB.y, 'rgba(235,223,174,.22)', 1.5); line(laneC.x, laneC.y, laneD.x, laneD.y, 'rgba(235,223,174,.22)', 1.5);
    for (let i = .07; i < .94; i += .1) { const p = lanePoint(i, Math.sin(i * 42) * 17); ellipse(p.x, p.y, 2.4, 1.4, 'rgba(89,91,72,.25)'); }
  }
  function drawBase(t, color, name, blue) {
    const p = lanePoint(t), r = blue ? 38 : 34;
    ellipse(p.x, p.y + 13, r * 1.45, r * .8, 'rgba(7,14,12,.3)');
    ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(-.16);
    ellipse(0, 0, r * 1.28, r * .82, blue ? 'rgba(75,150,199,.25)' : 'rgba(201,83,73,.21)', blue ? 'rgba(129,195,230,.65)' : 'rgba(233,139,112,.58)', 2);
    ellipse(0, 0, r * .82, r * .53, blue ? '#3d6170' : '#714743', blue ? '#8bbdd1' : '#cb8870', 2);
    // Keep / crystal
    ctx.fillStyle = blue ? '#567d83' : '#85544b'; path([{x:-r*.49,y:3},{x:-r*.37,y:-r*.43},{x:0,y:-r*.67},{x:r*.37,y:-r*.43},{x:r*.49,y:3},{x:0,y:r*.3}]); ctx.fill();
    line(-r*.36,-r*.42,0,-r*.67,blue?'#a1d9e8':'#ffc1a0',2); line(r*.36,-r*.42,0,-r*.67,blue?'#a1d9e8':'#ffc1a0',2);
    ellipse(0, -r * .16, 5, 6, blue ? '#a4e7ef' : '#ffb08f'); ellipse(0,-r*.16,10,11,blue?'rgba(130,226,240,.15)':'rgba(255,154,123,.17)');
    ctx.restore();
    label(name, p.x, p.y + r + 21, blue ? '#bce6ed' : '#ffbca8');
  }
  function label(text, x, y, color) { ctx.save(); ctx.font = '600 9px Manrope, sans-serif'; ctx.textAlign = 'center'; ctx.fillStyle = 'rgba(9,17,14,.68)'; ctx.fillText(text, x + 1, y + 1); ctx.fillStyle = color; ctx.fillText(text, x, y); ctx.restore(); }
  function drawTower(p) {
    const pulse = .5 + .5 * Math.sin(elapsed * 2.1);
    ellipse(p.x, p.y + 17, 35, 18, 'rgba(8,13,12,.37)');
    // Tower platform
    ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(-.16);
    ellipse(0, 8, 36, 22, '#514f3c', '#d2ad83', 1.5); ellipse(0, 3, 30, 18, '#786647', '#c4aa78', 1.5); ellipse(0, -1, 24, 14, '#907650', '#e3c28a', 1.2);
    // Stone body
    path([{x:-17,y:0},{x:-14,y:-36},{x:-9,y:-45},{x:9,y:-45},{x:14,y:-36},{x:17,y:0},{x:0,y:8}]); ctx.fillStyle='#885f51'; ctx.fill(); ctx.strokeStyle='#c48c70'; ctx.lineWidth=1.4; ctx.stroke();
    path([{x:-14,y:-36},{x:-9,y:-45},{x:0,y:-40},{x:0,y:-5},{x:-16,y:0}]); ctx.fillStyle='#a5755e'; ctx.fill();
    path([{x:0,y:-40},{x:9,y:-45},{x:14,y:-36},{x:17,y:0},{x:0,y:-5}]); ctx.fillStyle='#704c45'; ctx.fill();
    // crown and glowing core
    path([{x:-15,y:-36},{x:-19,y:-47},{x:-11,y:-45},{x:-6,y:-53},{x:0,y:-47},{x:7,y:-54},{x:11,y:-44},{x:18,y:-48},{x:14,y:-34}]); ctx.fillStyle='#a87261'; ctx.fill(); ctx.strokeStyle='#e2aa89'; ctx.stroke();
    ellipse(0,-30,5,8,`rgba(255,131,105,${.6 + pulse * .3})`); ellipse(0,-30,11,13,`rgba(238,107,81,${.08 + pulse * .08})`);
    ctx.restore();
    // selection / range ring
    if (attackMode && !towerState.dead) { ctx.save(); ctx.setLineDash([5,6]); ctx.lineWidth=1; ctx.strokeStyle='rgba(255,171,145,.47)'; ctx.beginPath(); ctx.ellipse(p.x,p.y+5,91,47,-.37,0,Math.PI*2); ctx.stroke(); ctx.restore(); }
    const barW = 76, bx = p.x - barW / 2, by = p.y - 78;
    roundedRect(bx, by, barW, 8, 4, 'rgba(14,15,14,.78)');
    roundedRect(bx + 1, by + 1, Math.max(0, (barW - 2) * towerState.hp / towerState.max), 6, 3, towerState.hp > 35 ? '#dd7163' : '#f1a05c');
    label(towerState.dead ? 'SENTINEL • FALLEN' : 'RED SENTINEL', p.x, by - 8, '#ffd0bd');
  }
  function roundedRect(x,y,w,h,r,fill) { ctx.beginPath(); ctx.roundRect(x,y,w,h,r); ctx.fillStyle=fill; ctx.fill(); }
  function drawHero(p) {
    const bob = Math.sin(elapsed * 8) * (hero.moving ? 2 : .8);
    ellipse(p.x, p.y + 10, 17, 8, 'rgba(7,13,12,.35)');
    // selection halo
    ellipse(p.x, p.y + 6, 23, 12, 'rgba(124,198,219,.13)', 'rgba(170,225,230,.54)', 1.2);
    // cape and body
    ctx.save(); ctx.translate(p.x, p.y + bob); ctx.rotate(Math.atan2(lanePoint(1).y-lanePoint(0).y,lanePoint(1).x-lanePoint(0).x));
    path([{x:-8,y:-3},{x:-12,y:9},{x:-4,y:7},{x:0,y:12},{x:6,y:6},{x:9,y:-4},{x:0,y:-9}]); ctx.fillStyle='#3d7680'; ctx.fill(); ctx.strokeStyle='#a6d4d0'; ctx.lineWidth=1; ctx.stroke();
    ellipse(0,-3,7,9,'#b8c5b6','#eff0d9',1); ellipse(0,-9,5,5,'#e1ddc2','#f8edc9',1);
    // shoulder / blade
    line(5,-3,12,-11,'#e1d3a6',2.2); line(12,-11,15,-14,'#f2e7c9',1.2);
    ctx.restore();
    // Hero health marker
    roundedRect(p.x-16,p.y-25,32,4,2,'rgba(8,13,12,.75)'); roundedRect(p.x-15,p.y-24,30,2,1,'#93d79b');
  }
  function drawProjectile() {
