import {createRequire} from 'node:module';import fs from 'node:fs';const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');const {chromium}=require('playwright');process.env.DISPLAY||=':'+fs.readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();const c=JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));const b=await chromium.launch(c.browser.launchOptions);const p=await b.newPage({viewport:{width:1440,height:900}});await p.goto('http://127.0.0.1:8765');await p.locator('#attackButton').click();await p.waitForTimeout(10000);console.log(await p.evaluate(()=>({obj:document.querySelector('#objectiveStatus').textContent,mini:document.querySelector('#miniHero').style.left,hp:document.querySelector('#heroHealthValue').textContent})));await b.close();
EOF

